function guessMealType(){const h=new Date().getHours();return h<11?'desayuno':h<16?'comida':h<20?'colacion':'cena'}
function setStatus(text,mode=''){els.status.className=`status-line ${mode}`;els.status.lastElementChild.textContent=text}
function normalizeText(value){return String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replaceAll('_',' ').replace(/\s+/g,' ').trim()}
function foodById(id){return FOOD_DATA.find(food=>food.id===id)}
function foodEmoji(food){if(!food)return '🍽️';if(food.custom)return '🏷️';if(FOOD_EMOJI[food.id])return FOOD_EMOJI[food.id];const text=normalizeText(`${food.name} ${food.aliases?.join(' ')||''}`);if(/egg|huevo|omelet/.test(text))return '🥚';if(/taco|tacos/.test(text))return '🌮';if(/chicken|pollo|poultry/.test(text))return '🍗';if(/beef|steak|res|arrachera/.test(text))return '🥩';if(/pork|cerdo|carnitas|ham|bacon/.test(text))return '🥓';if(/fish|salmon|tuna|pescado|shrimp|camaron|seafood/.test(text))return '🐟';if(/rice|arroz|paella/.test(text))return '🍚';if(/pasta|noodle|ramen|spaghetti|macaroni/.test(text))return '🍝';if(/bread|pan|sandwich/.test(text))return '🍞';if(/bean|lentil|chickpea|frijol/.test(text))return '🫘';if(/apple|manzana/.test(text))return '🍎';if(/banana|platano/.test(text))return '🍌';if(/orange|naranja/.test(text))return '🍊';if(/avocado|aguacate/.test(text))return '🥑';if(/vegetable|salad|verdura/.test(text))return '🥗';if(/yogurt|yogur|milk|leche|cheese|queso/.test(text))return '🥛';if(/soup|sopa|pozole|curry/.test(text))return '🍲';if(/pizza/.test(text))return '🍕';if(/cake|pastel|dessert|helado|ice cream|chocolate|cookie/.test(text))return '🍰';return '🍽️'}
function gramsFor(food){return Number(food?.portionG||food?.portionGrams||100)}
function makeItem(food,grams,unit,amount,gramsPerUnit){const resolvedUnit=unit??food.portionUnit??'g';const perUnit=gramsPerUnit??(resolvedUnit==='g'?1:(food.portionGrams||grams||1));const resolvedAmount=amount??(resolvedUnit==='g'?grams:grams/perUnit);return {...food,grams,unit:resolvedUnit,amount:resolvedAmount,gramsPerUnit:perUnit}}
function macroFor(food,grams){const ratio=(Number(grams)||0)/100;return {kcal:food.kcal*ratio,p:food.p*ratio,c:food.c*ratio,f:food.f*ratio}}
function macroLabel(food,grams){const m=macroFor(food,grams);return `${Math.round(m.kcal)} kcal · P ${m.p.toFixed(1)} g · C ${m.c.toFixed(1)} g · G ${m.f.toFixed(1)} g`}
function compactNumber(value){return Number(value).toFixed(1).replace(/\.0$/,'')}
function persistFavorites(){try{localStorage.setItem('comida-clara-favorites',JSON.stringify([...favoriteFoodIds]))}catch(error){console.warn('No se pudieron guardar los favoritos',error)}}
function toggleFavorite(food){if(!food)return;if(favoriteFoodIds.has(food.id))favoriteFoodIds.delete(food.id);else favoriteFoodIds.add(food.id);persistFavorites();renderFoodViews();renderFoodBrowser();if(!els.searchResults.hidden)showSearchResults()}
function renderFoodViews(){const views=[['favorites',`⭐ Favoritos${favoriteFoodIds.size?` · ${favoriteFoodIds.size}`:''}`],['all','🍽️ Todo el catálogo']];els.foodViews.replaceChildren();views.forEach(([key,label])=>{const button=document.createElement('button');button.type='button';button.className='food-view'+(activeFoodView===key?' active':'');button.setAttribute('aria-pressed',String(activeFoodView===key));button.textContent=label;button.onclick=()=>{activeFoodView=key;shownFoodCount=36;renderFoodViews();renderFoodBrowser()};els.foodViews.append(button)})}
function foodForSelection(food){if(food?.id&&RECIPE_CONFIGS[food.id]){loadRecipeTemplate(food.id);return}addFoodToDraft(food)}
function addFoodToDraft(food){if(!food)return;const current=mealFoods.find(item=>item.id===food.id);if(current){if(current.unit==='g'){current.grams+=gramsFor(food);current.amount=current.grams}else{current.amount+=1;current.grams=current.amount*current.gramsPerUnit}}else mealFoods.push(makeItem(food,gramsFor(food)));renderFoodItems();updateNutrition();setStatus(`${foodEmoji(food)} ${food.name} añadido. Puedes ajustar piezas o gramos; el aporte de macros aparece debajo.`)}
function renderFavoriteButton(food,className='favorite-toggle'){const button=document.createElement('button');button.type='button';const favorite=favoriteFoodIds.has(food.id);button.className=className+(favorite?' is-favorite':'');button.textContent=favorite?'★':'☆';button.setAttribute('aria-label',favorite?`Quitar ${food.name} de favoritos`:`Añadir ${food.name} a favoritos`);button.title=favorite?'Quitar de favoritos':'Añadir a favoritos';button.onclick=event=>{event.stopPropagation();toggleFavorite(food)};return button}
function renderFoodCard(food){const card=document.createElement('article');card.className='food-card';const add=document.createElement('button');add.type='button';add.className='food-card-main';add.setAttribute('aria-label','Añadir '+food.name+', '+Math.round(food.kcal)+' kcal por 100 gramos');add.innerHTML='<span class="food-card-emoji">'+foodEmoji(food)+'</span><span class="food-card-copy"><strong>'+escapeHtml(food.name)+'</strong><small><b>'+Math.round(food.kcal)+' kcal</b> / 100 g<br>P '+compactNumber(food.p)+' · C '+compactNumber(food.c)+' · G '+compactNumber(food.f)+' g'+(RECIPE_CONFIGS[food.id]?'<br><em>Plantilla editable por ingredientes</em>':'')+'</small></span>';add.onclick=()=>foodForSelection(food);card.append(add,renderFavoriteButton(food));return card}
function renderFoodBrowser(){const query=normalizeText(els.search.value);let foods=query?searchFoods(query,80):activeFoodView==='favorites'?FOOD_DATA.filter(food=>favoriteFoodIds.has(food.id)).sort((a,b)=>a.name.localeCompare(b.name,'es')):FOOD_DATA.slice().sort((a,b)=>a.name.localeCompare(b.name,'es'));const visible=foods.slice(0,shownFoodCount);els.foodBrowser.replaceChildren();$('#catalogCount').textContent=query?`${foods.length} coincidencias`:activeFoodView==='favorites'?`${foods.length} guardados`:`${foods.length} alimentos`;if(!visible.length){const empty=document.createElement('p');empty.className='catalog-empty';empty.textContent=query?'No encontré coincidencias. Prueba otro nombre en español o inglés.':activeFoodView==='favorites'?'Aún no tienes favoritos. Busca un plato o ingrediente y toca ☆ para guardarlo aquí.':'No hay alimentos disponibles en el catálogo.';els.foodBrowser.append(empty);return}visible.forEach(food=>els.foodBrowser.append(renderFoodCard(food)));if(foods.length>visible.length){const more=document.createElement('button');more.type='button';more.className='show-more-foods';more.textContent=`Mostrar ${Math.min(36,foods.length-visible.length)} más`;more.onclick=()=>{shownFoodCount+=36;renderFoodBrowser()};els.foodBrowser.append(more)}}
function searchFoods(query,limit=12){if(!query)return [];return FOOD_DATA.map(food=>{const name=normalizeText(food.name);const aliases=(food.aliases||[]).map(normalizeText);let rank=99;if(name===query||aliases.includes(query))rank=0;else if(name.startsWith(query))rank=1;else if(aliases.some(alias=>alias.startsWith(query)))rank=2;else if(name.includes(query)||aliases.some(alias=>alias.includes(query)))rank=3;return {food,rank}}).filter(result=>result.rank<99).sort((a,b)=>a.rank-b.rank||a.food.name.localeCompare(b.food.name,'es')).slice(0,limit).map(result=>result.food)}
function saveCustomFood(event){event.preventDefault();const name=$('#customFoodName').value.trim();const serving=Number($('#customFoodServing').value);const kcal=Number($('#customFoodKcal').value);const protein=Number($('#customFoodProtein').value);const carbs=Number($('#customFoodCarbs').value);const fat=Number($('#customFoodFat').value);if(!name||serving<=0||![kcal,protein,carbs,fat].every(value=>Number.isFinite(value)&&value>=0))return;const food={id:'custom_'+Date.now().toString(36),name,kcal:kcal*100/serving,p:protein*100/serving,c:carbs*100/serving,f:fat*100/serving,aliases:[],portionG:serving,portionUnit:'porciones',portionGrams:serving,custom:true};customFoods.push(food);FOOD_DATA.push(food);favoriteFoodIds.add(food.id);persistFavorites();try{localStorage.setItem('comida-clara-custom-foods',JSON.stringify(customFoods))}catch(error){console.warn('No se pudo guardar el alimento',error)}$('#customFoodForm').reset();activeFoodView='favorites';renderFoodViews();renderFoodBrowser();addFoodToDraft(food);const feedback=$('#customFoodFeedback');feedback.textContent='🏷️ '+name+' guardado en Favoritos y añadido a tu comida.';feedback.hidden=false}
function showSearchResults(){const query=normalizeText(els.search.value);els.searchResults.replaceChildren();if(!query){els.searchResults.hidden=true;return}const matches=searchFoods(query,12);if(!matches.length){const empty=document.createElement('div');empty.className='search-result-empty';empty.textContent='Sin coincidencias. Prueba español, inglés o un nombre más específico.';els.searchResults.append(empty);els.searchResults.hidden=false;return}matches.forEach(food=>{const row=document.createElement('div');row.className='search-result-row';const add=document.createElement('button');add.type='button';add.className='search-result';add.innerHTML='<span class="search-result-emoji">'+foodEmoji(food)+'</span><span class="search-result-name">'+escapeHtml(food.name)+'</span><small>'+Math.round(food.kcal)+' kcal/100 g</small>';add.onclick=()=>{foodForSelection(food);els.search.value='';els.searchResults.hidden=true;renderFoodBrowser()};row.append(add,renderFavoriteButton(food,'search-favorite-toggle'));els.searchResults.append(row)});els.searchResults.hidden=false}
function chooseMealType(type){if(!MEAL_TYPES[type])return;mealTypeCurrent=type;$$('.meal-type').forEach(button=>button.classList.toggle('active',button.dataset.mealType===type));$('#mealTypeLabel').textContent=`· ${MEAL_TYPES[type].label}`}
function loadRecipeTemplate(type,count){const config=RECIPE_CONFIGS[type];if(!config)return;const amount=count||config.defaultCount;recipeType=type;servingCount=amount;els.servings.value=amount;els.recipeControls.hidden=false;$('#servingsLabel').textContent=config.label;const base=config.ingredients.map(([id,perServing,unit])=>{const food=foodById(id);if(!food)return null;if(unit==='piezas'||unit==='huevos'||unit==='claras'){const gramsPerUnit=Number(food.portionGrams||food.portionG||50);return makeItem(food,amount*perServing*gramsPerUnit,unit,amount*perServing,gramsPerUnit)}return makeItem(food,amount*perServing,'g',amount*perServing,1)}).filter(Boolean).map(item=>({...item,scaleWithServings:true}));mealFoods=base;renderFoodItems();updateNutrition();setStatus('🍽️ Desglose sugerido para '+amount+' '+config.name.toLowerCase()+'. Ajusta cantidades, ingredientes y preparación a tu receta.')}
function loadTacoTemplate(type,count){loadRecipeTemplate('tacos_'+type,count)}

function renderFoodItems(){els.foodItems.replaceChildren();if(!mealFoods.length){const empty=document.createElement('div');empty.className='draft-empty';empty.innerHTML='<span>🍽️</span><p>Tu desglose aparecerá aquí.</p><small>Añade alimentos desde el catálogo o busca un ingrediente arriba.</small>';els.foodItems.append(empty);updateNutrition();return}mealFoods.forEach((food,index)=>{const row=document.createElement('div');row.className='food-row';const nameWrap=document.createElement('div');nameWrap.className='food-name-wrap';const emoji=document.createElement('span');emoji.className='food-row-emoji';emoji.textContent=foodEmoji(food);const name=document.createElement('div');name.className='food-name';name.textContent=food.name;const detail=document.createElement('small');detail.className='food-macro-detail';detail.textContent=macroLabel(food,food.grams);name.append(detail);nameWrap.append(emoji,name);const controls=document.createElement('div');controls.className='food-controls';const grams=document.createElement('input');grams.className='food-amount';grams.type='number';grams.min='0';grams.step='1';grams.value=Number(food.grams.toFixed(1));grams.setAttribute('aria-label',`Gramos de ${food.name}`);grams.inputMode='decimal';const gUnit=document.createElement('span');gUnit.className='food-unit';gUnit.textContent='g';if(food.unit==='g'){grams.oninput=()=>{food.grams=Math.max(0,Number(grams.value)||0);food.amount=food.grams;detail.textContent=macroLabel(food,food.grams);updateNutrition()};controls.append(grams,gUnit)}else{const qty=document.createElement('input');qty.className='food-quantity';qty.type='number';qty.min='0';qty.step='0.5';qty.value=Number(food.amount.toFixed(1));qty.setAttribute('aria-label',`Cantidad de ${food.name}`);qty.inputMode='decimal';const unit=document.createElement('span');unit.className='food-unit';unit.textContent=food.unit;const eq=document.createElement('span');eq.className='food-equals';eq.textContent='≈';qty.oninput=()=>{food.amount=Math.max(0,Number(qty.value)||0);food.grams=food.amount*food.gramsPerUnit;grams.value=Number(food.grams.toFixed(1));detail.textContent=macroLabel(food,food.grams);updateNutrition()};grams.oninput=()=>{food.grams=Math.max(0,Number(grams.value)||0);food.amount=food.grams/food.gramsPerUnit;qty.value=Number(food.amount.toFixed(1));detail.textContent=macroLabel(food,food.grams);updateNutrition()};controls.append(qty,unit,eq,grams,gUnit)}const remove=document.createElement('button');remove.type='button';remove.className='food-remove';remove.textContent='×';remove.setAttribute('aria-label',`Quitar ${food.name}`);remove.onclick=()=>{mealFoods.splice(index,1);renderFoodItems()};row.append(nameWrap,controls,remove);els.foodItems.append(row)})}
function updateNutrition(){const total=mealFoods.reduce((sum,food)=>{const value=macroFor(food,food.grams);return {kcal:sum.kcal+value.kcal,p:sum.p+value.p,c:sum.c+value.c,f:sum.f+value.f}},{kcal:0,p:0,c:0,f:0});els.cal.textContent=Math.round(total.kcal);els.protein.textContent=`${total.p.toFixed(1)} g`;els.carbs.textContent=`${total.c.toFixed(1)} g`;els.fat.textContent=`${total.f.toFixed(1)} g`;$('#saveMeal').disabled=!mealFoods.length}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function logProteinShake(){const scoops=Math.max(0,Number($('#proteinScoops').value)||0);if(!scoops)return;const perScoop={p:Math.max(0,Number($('#proteinPerScoop').value)||0),c:Math.max(0,Number($('#proteinCarbsPerScoop').value)||0),f:Math.max(0,Number($('#proteinFatPerScoop').value)||0)};const kcalField=$('#proteinKcalPerScoop').value.trim();const kcalPerScoop=kcalField===''?perScoop.p*4+perScoop.c*4+perScoop.f*9:Math.max(0,Number(kcalField)||0);const total={p:scoops*perScoop.p,kcal:scoops*kcalPerScoop,c:scoops*perScoop.c,f:scoops*perScoop.f};meals.push({day:todayKey,foods:[{id:'protein_powder',name:'Shake de proteína',grams:total.p,amount:scoops,unit:'scoop',kcalPer100:kcalPerScoop*100/Math.max(perScoop.p,1),pPer100:perScoop.p*100/Math.max(perScoop.p,1),cPer100:perScoop.c*100/Math.max(perScoop.p,1),fPer100:perScoop.f*100/Math.max(perScoop.p,1)}],grams:total.p,kcal:Math.round(total.kcal),p:+total.p.toFixed(1),c:+total.c.toFixed(1),f:+total.f.toFixed(1),scoops,proteinGrams:+total.p.toFixed(1),proteinShake:true,mealType:'colacion',time:new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}),photo:'',recipeType:'',dishClass:''});persist();const feedback=$('#proteinLogFeedback');feedback.textContent=`🥤 Añadido: ${scoops} ${scoops===1?'scoop':'scoops'} · ${total.p.toFixed(1)} g de proteína.`;feedback.hidden=false}
function renderHistory(){els.history.replaceChildren();if(!meals.length){const empty=document.createElement('div');empty.className='history-empty';empty.textContent='Tus comidas de hoy aparecerán aquí, cada una con su desglose de macros.';els.history.append(empty)}else meals.slice().reverse().forEach((meal,index)=>{const item=document.createElement('article');item.className='history-item';const type=MEAL_TYPES[meal.mealType]||MEAL_TYPES.comida;const foods=Array.isArray(meal.foods)?meal.foods:[];const emojiList=[...new Set(foods.map(saved=>saved.id==='protein_powder'?'🥤':foodEmoji(foodById(saved.id)||{name:saved.name,aliases:[]})))].slice(0,4).join(' ');const summary=document.createElement('div');summary.className='history-summary';const icons=document.createElement('span');icons.className='history-emojis';icons.textContent=emojiList||'🍽️';const info=document.createElement('div');info.className='history-info';const title=document.createElement('strong');title.textContent=`${type.label} · ${RECIPE_CONFIGS[meal.recipeType]?.name||foods.map(saved=>saved.name).join(' + ')||'Comida'}`;const meta=document.createElement('span');meta.textContent=`${meal.time||''} · ${meal.kcal} kcal · P ${Number(meal.p||0).toFixed(1)} · C ${Number(meal.c||0).toFixed(1)} · G ${Number(meal.f||0).toFixed(1)} g`;info.append(title,meta);summary.append(icons,info);const kcal=document.createElement('span');kcal.className='history-kcal';kcal.textContent=`${meal.kcal} kcal`;const remove=document.createElement('button');remove.type='button';remove.className='remove-meal';remove.setAttribute('aria-label','Quitar comida');remove.textContent='×';remove.onclick=()=>{meals.splice(meals.length-1-index,1);persist()};item.append(summary,kcal,remove);if(foods.length){const details=document.createElement('details');details.className='history-breakdown';const label=document.createElement('summary');label.textContent='Ver macros por alimento';const list=document.createElement('div');list.className='history-breakdown-list';foods.forEach(saved=>{const known=foodById(saved.id);const per100={kcal:Number(saved.kcalPer100??known?.kcal??0),p:Number(saved.pPer100??known?.p??0),c:Number(saved.cPer100??known?.c??0),f:Number(saved.fPer100??known?.f??0)};const m={kcal:per100.kcal*(Number(saved.grams)||0)/100,p:per100.p*(Number(saved.grams)||0)/100,c:per100.c*(Number(saved.grams)||0)/100,f:per100.f*(Number(saved.grams)||0)/100};const line=document.createElement('div');line.className='history-breakdown-row';const left=document.createElement('span');left.textContent=`${saved.id==='protein_powder'?'🥤':foodEmoji(known||{name:saved.name,aliases:[]})} ${saved.name} · ${saved.unit==='scoop'?`${saved.amount} scoop(s)`:saved.unit==='g'?`${Math.round(saved.grams)} g`:`${saved.amount} ${saved.unit} (${Math.round(saved.grams)} g)`}`;const right=document.createElement('span');right.textContent=`${Math.round(m.kcal)} kcal · P ${m.p.toFixed(1)} · C ${m.c.toFixed(1)} · G ${m.f.toFixed(1)} g`;line.append(left,right);list.append(line)});details.append(label,list);item.append(details)}els.history.append(item)});const totals=meals.reduce((sum,meal)=>({k:sum.k+(Number(meal.kcal)||0),p:sum.p+(Number(meal.p)||0),c:sum.c+(Number(meal.c)||0),f:sum.f+(Number(meal.f)||0)}),{k:0,p:0,c:0,f:0});$('#dailyCalories').textContent=Math.round(totals.k);$('#dailyProtein').textContent=`${totals.p.toFixed(1)} g`;$('#dailyCarbs').textContent=`${totals.c.toFixed(1)} g`;$('#dailyFat').textContent=`${totals.f.toFixed(1)} g`;$('#mealCount').textContent=`${meals.length} ${meals.length===1?'comida':'comidas'}`}
function persist(){allMeals=[...allMeals.filter(meal=>meal.day!==todayKey),...meals];try{localStorage.setItem('comida-clara-meals',JSON.stringify(allMeals))}catch(error){console.warn('No se pudo guardar el registro local',error)}renderHistory()}
function saveCurrentMeal(){if(!mealFoods.length)return;const total=mealFoods.reduce((sum,food)=>{const value=macroFor(food,food.grams);return {k:sum.k+value.kcal,p:sum.p+value.p,c:sum.c+value.c,f:sum.f+value.f,grams:sum.grams+(Number(food.grams)||0)}},{k:0,p:0,c:0,f:0,grams:0});meals.push({day:todayKey,foods:mealFoods.map(food=>({id:food.id,name:food.name,grams:food.grams,amount:food.amount,unit:food.unit,kcalPer100:food.kcal,pPer100:food.p,cPer100:food.c,fPer100:food.f})),grams:total.grams,kcal:Math.round(total.k),p:+total.p.toFixed(1),c:+total.c.toFixed(1),f:+total.f.toFixed(1),mealType:mealTypeCurrent,time:new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}),photo:'',recipeType,dishClass:recipeType||mealFoods.map(food=>food.id).join('+'),servingCount});persist();mealFoods=[];recipeType='';els.recipeControls.hidden=true;renderFoodItems();setStatus('Comida guardada. Puedes registrar la siguiente sin salir de esta pantalla.');$('#foodLogTitle').scrollIntoView({behavior:'smooth',block:'start'})}
function exportDiary(){if(!allMeals.length){alert('Todavía no hay registros para exportar.');return}const backup={format:'comida-clara-diary-v2',exportedAt:new Date().toISOString(),meals:allMeals,customFoods,dailyGoals:Object.fromEntries(dailyGoalIds.map(id=>[id,$('#'+id).value])),proteinSettings:Object.fromEntries(proteinSettingIds.map(id=>[id,$('#'+id).value]))};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='comida-clara-respaldo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#customFoodForm').addEventListener('submit',saveCustomFood);els.search.addEventListener('input',()=>{shownFoodCount=36;renderFoodBrowser();showSearchResults()});els.search.addEventListener('focus',showSearchResults);document.addEventListener('click',event=>{if(!event.target.closest('.food-search-wrap'))els.searchResults.hidden=true});$$('.meal-type').forEach(button=>button.addEventListener('click',()=>chooseMealType(button.dataset.mealType)));$$('[data-taco]').forEach(button=>button.addEventListener('click',()=>loadTacoTemplate(button.dataset.taco)));$$('[data-recipe]').forEach(button=>button.addEventListener('click',()=>loadRecipeTemplate(button.dataset.recipe))); $('#clearDraft').addEventListener('click',()=>{mealFoods=[];recipeType='';els.recipeControls.hidden=true;renderFoodItems();setStatus('Desglose vacío; elige alimentos para empezar.')});els.servings.addEventListener('input',()=>{if(!recipeType)return;const next=Math.max(1,Math.min(20,Number(els.servings.value)||1));const factor=next/servingCount;mealFoods.filter(food=>food.scaleWithServings).forEach(food=>{food.grams*=factor;food.amount*=factor});servingCount=next;renderFoodItems()});$('#logProtein').addEventListener('click',logProteinShake);$('#saveMeal').addEventListener('click',saveCurrentMeal);$('#clearDay').addEventListener('click',()=>{if(meals.length&&confirm('¿Borrar las comidas registradas hoy?')){meals=[];persist()}});$('#exportExamples').addEventListener('click',exportDiary);const dialog=$('#aboutDialog');$('#aboutButton').onclick=()=>dialog.showModal();$('#closeDialog').onclick=()=>dialog.close();$('#closeDialogAction').onclick=()=>dialog.close();let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('#installButton').hidden=false});$('#installButton').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installButton').hidden=true}else alert('En Safari, toca Compartir y luego “Agregar a pantalla de inicio”.')};if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);for(const id of dailyGoalIds)$('#'+id).addEventListener('input',()=>{const goals=Object.fromEntries(dailyGoalIds.map(key=>[key,$('#'+key).value]));try{localStorage.setItem('comida-clara-daily-goals',JSON.stringify(goals))}catch(error){console.warn('No se pudieron guardar los objetivos',error)}});for(const id of proteinSettingIds)$('#'+id).addEventListener('change',()=>{const saved=Object.fromEntries(proteinSettingIds.map(key=>[key,$('#'+key).value]));try{localStorage.setItem('comida-clara-protein-settings',JSON.stringify(saved))}catch{}});chooseMealType(mealTypeCurrent);renderFoodViews();renderFoodBrowser();renderFoodItems();renderHistory();$('#todayDate').textContent=new Intl.DateTimeFormat('es-MX',{weekday:'short',day:'numeric',month:'short'}).format(new Date());
